// Golden files: invoices worked out by hand (each file's `working` shows the
// arithmetic) and never regenerated by the engine. A golden file the code
// rewrites when it disagrees is a snapshot of the bug.
import { describe, expect, it } from 'vitest';

import exclusiveNoDiscount from './golden/01-exclusive-no-discount.json' with { type: 'json' };
import exclusiveFlatDiscountTaxedService from './golden/02-exclusive-flat-discount-taxed-service.json' with { type: 'json' };
import inclusiveNoDiscount from './golden/03-inclusive-no-discount.json' with { type: 'json' };
import inclusivePercentDiscountUntaxedService from './golden/04-inclusive-percent-discount-untaxed-service.json' with { type: 'json' };
import compositionDiscountService from './golden/05-composition-discount-service.json' with { type: 'json' };
import unregisteredInclusive from './golden/06-unregistered-inclusive.json' with { type: 'json' };
import inclusivePaiseBoundaries from './golden/07-inclusive-paise-boundaries.json' with { type: 'json' };
import exclusiveFullDiscount from './golden/08-exclusive-full-discount.json' with { type: 'json' };
import syncPushFixtureInvoice from './golden/09-sync-push-fixture-invoice.json' with { type: 'json' };
import inclusiveCompCapped from './golden/10-inclusive-comp-capped-at-taxable-value.json' with { type: 'json' };
import remainderTieHigherRate from './golden/11-exclusive-remainder-tie-goes-to-the-higher-rate.json' with { type: 'json' };
import type { InvoiceInput } from './totals.js';
import { computeInvoice } from './totals.js';

const goldens = {
  '01 exclusive, no discount': exclusiveNoDiscount,
  '02 exclusive, flat discount, taxed service charge': exclusiveFlatDiscountTaxedService,
  '03 inclusive, no discount': inclusiveNoDiscount,
  '04 inclusive, percent discount, untaxed service charge': inclusivePercentDiscountUntaxedService,
  '05 composition, discount, service charge': compositionDiscountService,
  '06 unregistered, inclusive': unregisteredInclusive,
  '07 inclusive, paise boundaries': inclusivePaiseBoundaries,
  '08 exclusive, 100% discount': exclusiveFullDiscount,
  '09 the sync contract fixture invoice': syncPushFixtureInvoice,
  '10 inclusive, a comp capped at the taxable value': inclusiveCompCapped,
  '11 exclusive, a remainder tie goes to the higher rate': remainderTieHigherRate,
};

describe('computeInvoice golden files', () => {
  it.each(Object.entries(goldens))('%s matches the hand-checked invoice', (_name, golden) => {
    const input = paise(golden.input) as InvoiceInput;
    expect(computeInvoice(input)).toEqual(paise(golden.expected));
  });

  // The server may hold the lines in another order than the till did; the
  // bill must not change with it (ADR 0028).
  it.each(Object.entries(goldens))(
    '%s gives the same invoice with its lines listed in reverse',
    (_name, golden) => {
      const input = paise(golden.input) as InvoiceInput;
      const expected = paise(golden.expected) as { lines: unknown[] };
      expect(computeInvoice({ ...input, lines: [...input.lines].reverse() })).toEqual({
        ...expected,
        lines: [...expected.lines].reverse(),
      });
    },
  );
});

/** Golden files hold paise as integer strings (JSON has no bigint); turn them back. */
function paise(value: unknown): unknown {
  if (typeof value === 'string' && /^-?\d+$/.test(value)) return BigInt(value);
  if (Array.isArray(value)) return value.map(paise);
  if (value !== null && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, entry]) => [key, paise(entry)]));
  }
  return value;
}
